  function render(){const project=api.getProject(),next=JSON.stringify(project.production?.publishing||null);const ownerKey=JSON.stringify([api.getWorkspaceId?.()??null,project.id]);if(owner!==ownerKey){if(busy)stop('프로젝트가 바뀌어 게시 자료 작성을 취소했어요.');owner=ownerKey;fingerprint='';thumbSerial++;}if(next!==fingerprint){fingerprint=next;if(!localThumbnailWrite)hydrate(project.production?.publishing);}refreshActions();tagPicker?.render();descriptionOptions?.render();}
