  descriptionOptions=setupDescriptionOptions({container:descriptionOptionsMount,prefix:'publishing',getPreferences:()=>getDescriptionPreferences(api.getProject()),getOwnerKey:()=>JSON.stringify([api.getWorkspaceId?.()??null,api.getProject().id]),canEdit:()=>!busy&&(!api.canMutate||api.canMutate()),onChange:async(preferences,{applySupport=false}={})=>{if(busy||api.canMutate&&!api.canMutate())throw new Error('현재 게시 자료 작업이 끝난 뒤 설명 설정을 바꿔 주세요.');const scope=taskScope(api),previous=getDescriptionPreferences(api.getProject());if(result&&(previous.support!==preferences.support||applySupport)){const value=captureEdits();value.description=composeSupportBlock(value.description,preferences.support);persist(value,preferences);}else{const mutate=api.mutateProductionMetadata||api.mutate;mutate(project=>setDescriptionPreferences(project,preferences));}await api.persist?.();if(!matchesScope(api,scope))throw new DOMException('프로젝트가 바뀌어 현재 설명 설정을 다시 확인해 주세요.','AbortError');}});
  tags.input.addEventListener('input',()=>tagPicker.render());
